import type { Block } from '../data/posts';

type Heading = Extract<Block, { type: 'heading' }>;

/** `inline` renders it inside the closed "On this page" disclosure, whose summary already names it. */
export default function TableOfContents({ blocks, inline = false }: { blocks: Block[]; inline?: boolean }) {
  const headings = blocks.filter((block): block is Heading => block.type === 'heading');
  if (headings.length === 0) return null;

  return (
    <nav className={inline ? 'toc toc--inline' : 'toc'} aria-labelledby="toc-heading" data-testid="toc">
      <h2 id="toc-heading" className={inline ? 'toc-heading visually-hidden' : 'toc-heading eyebrow'}>
        On this page
      </h2>
      <ol className="toc-list">
        {headings.map((heading) => (
          <li key={heading.id} className={heading.level === 3 ? 'toc-item toc-item-nested' : 'toc-item'}>
            <a href={`#${heading.id}`} className="toc-link" data-testid="toc-link">
              {heading.text}
            </a>
          </li>
        ))}
      </ol>
    </nav>
  );
}
EOF
